import ledger


def _encode(cents):
    """Encode an integer minor-unit amount as '<sign><digits>#<check>'."""
    cents = int(cents)
    sign = '+' if cents >= 0 else '-'
    digits = str(abs(cents))
    check = sum(int(d) for d in digits) % 10
    return "{}{}#{}".format(sign, digits, check)


def record(acct, cents, note):
    """Post `cents` (minor units) to `acct` with memo `note`; return new entry id."""
    return ledger.post(acct, _encode(cents), note)

